def bounded_run_length_compression(word):
    answer=[];index=0
    while index<len(word):
        end=index
        while end<len(word) and word[end]==word[index] and end-index<9:end+=1
        answer.append(str(end-index)+word[index]);index=end
    return ''.join(answer)

